+    cursor = current.kind === "field" ? (cursor as Record<string, unknown>)[current.name] : (cursor as readonly unknown[])[current.index];
+  }
+  const last = segments[segments.length - 1]!;
+  if (cursor === null || cursor === undefined) return;
+  if (last.kind === "field") delete (cursor as Record<string, unknown>)[last.name];
+  else (cursor as unknown[])[last.index] = undefined;
+}
+// #endregion Paths
+
+// #region Expressions
+export interface SpatialKernel {
+  readonly id?: string;
+  call?(name: string, args: Readonly<Record<string, unknown>>, runtime: RuntimeContext): unknown | Promise<unknown>;
+  query?(name: string, args: Readonly<Record<string, unknown>>, runtime: RuntimeContext): unknown | Promise<unknown>;
+  openTransaction?(runtime: RuntimeContext): void | Promise<void>;
+  commitTransaction?(runtime: RuntimeContext): void | Promise<void>;
+  rollbackTransaction?(runtime: RuntimeContext): void | Promise<void>;
+  requestPreview?(runtime: RuntimeContext): void | Promise<void>;
+  resolveEditable?(runtime: RuntimeContext): unknown | Promise<unknown>;
+}
+
+export interface RuntimeContext {
+  readonly modelSpace: ModelSpace;
+  readonly model: Model;
+  readonly kernel: SpatialKernel;
+}
+
+export interface ExpressionEnvironment {
+  readonly context: Record<string, unknown>;
+  readonly event: Record<string, unknown>;
+  readonly params: Record<string, unknown>;
+  readonly variables: Record<string, unknown>;
+  readonly runtime: RuntimeContext;
+}
+
+function asVec3(value: unknown): Vec3 {
+  if (Array.isArray(value) && value.length >= 3) return [Number(value[0] ?? 0), Number(value[1] ?? 0), Number(value[2] ?? 0)];
+  return [0, 0, 0];
+}
+
+function vec3Distance(left: Vec3, right: Vec3): number {
+  return Math.hypot(right[0] - left[0], right[1] - left[1], right[2] - left[2]);
+}
+
+export async function evalExpression(expression: SpatialExpression, environment: ExpressionEnvironment): Promise<unknown> {
+  switch (expression.kind) {
+    case "const":
+      return expression.value;
+    case "path": {
+      const root = expression.root === "context" ? environment.context : expression.root === "event" ? environment.event : environment.params;
+      return readPathSegments(root, expression.segments);
+    }
+    case "var":
+      return environment.variables[expression.name];
+    case "let": {
+      const scoped = { ...environment.variables };
+      for (const binding of expression.bindings) scoped[binding.name] = await evalExpression(binding.value, { ...environment, variables: scoped });
+      return evalExpression(expression.in, { ...environment, variables: scoped });
+    }
+    case "exists": {
+      const root = expression.target.root === "context" ? environment.context : expression.target.root === "event" ? environment.event : environment.params;
+      return readPathSegments(root, expression.target.segments) !== undefined;
+    }
+    case "notEmpty": {
+      const root = expression.target.root === "context" ? environment.context : expression.target.root === "event" ? environment.event : environment.params;
+      const value = readPathSegments(root, expression.target.segments);
+      if (Array.isArray(value)) return value.length > 0;
+      if (typeof value === "string") return value.length > 0;
+      return value !== null && value !== undefined;
+    }
+    case "all": {
+      for (const argument of expression.args) {
+        if (!(await evalExpression(argument, environment))) return false;
+      }
+      return true;
+    }
+    case "any": {
+      for (const argument of expression.args) {
+        if (await evalExpression(argument, environment)) return true;
+      }
+      return false;
+    }
+    case "not":
+      return !(await evalExpression(expression.arg, environment));
+    case "abs":
+      return Math.abs(Number(await evalExpression(expression.arg, environment)));
+    case "distance":
+      return vec3Distance(asVec3(await evalExpression(expression.a, environment)), asVec3(await evalExpression(expression.b, environment)));
+    case "kernel.call": {
+      const args = await evalExpressionMap(expression.args ?? {}, environment);
+      if (!environment.runtime.kernel.call) return null;
+      return environment.runtime.kernel.call(expression.function, args, environment.runtime);
+    }
+    case "binop": {
+      const left = await evalExpression(expression.left, environment);
+      const right = await evalExpression(expression.right, environment);
+      switch (expression.op) {
+        case "==":
+          return left === right;
+        case "!=":
+          return left !== right;
+        case ">":
+          return Number(left) > Number(right);
+        case "<":
+          return Number(left) < Number(right);
+        case ">=":
+          return Number(left) >= Number(right);
+        case "<=":
+          return Number(left) <= Number(right);
+        case "+":
+          return Number(left) + Number(right);
+        case "-":
+          return Number(left) - Number(right);
+        case "*":
+          return Number(left) * Number(right);
+        case "/":
+          return Number(left) / Number(right);
+      }
+    }
+    case "fold": {
+      const [left, right] = expression.args;
+      const a = Number(await evalExpression(left, environment));
+      const b = Number(await evalExpression(right, environment));
+      return expression.op === "min" ? Math.min(a, b) : Math.max(a, b);
+    }
+  }
+}
+
+async function evalExpressionMap(
+  input: Readonly<Record<string, SpatialExpression>>,
+  environment: ExpressionEnvironment,
+): Promise<Record<string, unknown>> {
+  const output: Record<string, unknown> = {};
+  for (const [key, value] of Object.entries(input)) output[key] = await evalExpression(value, environment);
+  return output;
+}
+// #endregion Expressions
+
+// #region Actions
+export interface ActionExecutionResult {
+  readonly ok: boolean;
+  readonly context: Record<string, unknown>;
+  readonly data: unknown;
+  readonly diff: unknown;
+  readonly patch: unknown;
+  readonly result: unknown;
+  readonly errors: readonly string[];
+}
+
+export interface ActionExecutionInput {
+  readonly action: string | ActionDefinition;
+  readonly params?: Readonly<Record<string, unknown>>;
+  readonly context?: Record<string, unknown>;
+  readonly runtime: RuntimeContext;
+}
+
+export class ActionRegistry {
+  private readonly actions = new Map<string, ActionDefinition>();
+
+  constructor(input?: readonly ActionDefinition[]) {
+    for (const action of input ?? []) this.register(action);
+  }
+
+  static withBuiltins(): ActionRegistry {
+    return new ActionRegistry(listBuiltinActions());
+  }
+
+  register(action: ActionDefinition): ActionDefinition {
+    this.actions.set(action.id, action);
+    return action;
+  }
+
+  get(id: string): ActionDefinition | null {
+    return this.actions.get(id) ?? null;
+  }
+
+  list(): readonly ActionDefinition[] {
+    return [...this.actions.values()];
+  }
+
+  async run(input: ActionExecutionInput): Promise<ActionExecutionResult> {
+    return runActionDefinition(input, this);
+  }
+}
+
+export async function runActionDefinition(
+  input: ActionExecutionInput,
+  registry: ActionRegistry = ActionRegistry.withBuiltins(),
+): Promise<ActionExecutionResult> {
+  const action = typeof input.action === "string" ? registry.get(input.action) : input.action;
+  if (!action) {
+    return {
+      ok: false,
+      context: { ...(input.context ?? {}) },
+      data: null,
+      diff: null,
+      patch: null,
+      result: null,
+      errors: [typeof input.action === "string" ? `Unknown action ${input.action}.` : "Unknown action."],
+    };
+  }
+  const context = { ...(input.context ?? {}) };
+  const variables: Record<string, unknown> = {};
+  const params = { ...(input.params ?? {}) };
+  const environment: ExpressionEnvironment = {
+    context,
+    event: {},
+    params,
+    variables,
+    runtime: input.runtime,
+  };
+  for (const variable of action.variables ?? []) variables[variable.name] = await evalExpression(variable.value, environment);
+  let data: unknown = null;
+  let diff: unknown = null;
+  let patch: unknown = null;
+  let result: unknown = null;
+  try {
+    for (const step of action.steps) {
+      switch (step.op) {
+        case "let":
+          variables[step.name] = await evalExpression(step.value, environment);
+          break;
+        case "setContext":
+          Object.assign(context, await evalExpressionMap(step.values, environment));
+          break;
+        case "deleteContext":
+          for (const key of step.keys) delete context[key];
+          break;
+        case "kernel.call": {
+          const args = await evalExpressionMap(step.args ?? {}, environment);
+          const value = input.runtime.kernel.call ? await input.runtime.kernel.call(step.function, args, input.runtime) : null;
+          if (step.assignTo) variables[step.assignTo] = value;
+          break;
+        }
+        case "guard": {
+          const passes = Boolean(await evalExpression(step.condition, environment));
+          if (!passes) throw new Error(step.message ?? `Guard failed in ${action.id}.`);
+          break;
+        }
+        case "action": {
+          const nested = await registry.run({
+            action: step.action,
+            params: await evalExpressionMap(step.params ?? {}, environment),
+            context,
+            runtime: input.runtime,
+          });
+          if (!nested.ok) throw new Error(nested.errors.join("\n"));
+          if (step.assignTo) variables[step.assignTo] = nested.result ?? nested.data;
+          data = nested.data;
+          diff = nested.diff;
+          patch = nested.patch;
+          result = nested.result;
+          break;
+        }
+        case "return":
+          diff = step.diff ? await evalExpression(step.diff, environment) : diff;
+          data = step.data ? await evalExpression(step.data, environment) : data;
+          patch = step.patch ? await evalExpression(step.patch, environment) : patch;
+          result = step.result ? await evalExpression(step.result, environment) : result;
+          return { ok: true, context, data, diff, patch, result, errors: [] };
+      }
+    }
+    return { ok: true, context, data, diff, patch, result, errors: [] };
+  } catch (error) {
+    return {
+      ok: false,
+      context,
+      data,
+      diff,
+      patch,
+      result,
+      errors: [error instanceof Error ? error.message : String(error)],
+    };
+  }
+}
+// #endregion Actions
+
+// #region Interactions
+export interface InteractionEvent {
+  readonly kind: string;
+  readonly [key: string]: unknown;
+}
+
+export interface InteractionSnapshot {
+  readonly interactionId: string;
+  readonly state: string;
+  readonly context: Record<string, unknown>;
+  readonly diagnostics: readonly InteractionDiagnostic[];
+  readonly display: readonly DisplayItem[];
+  readonly emittedEvents: readonly InteractionEvent[];
+  readonly previewRequested: boolean;
+  readonly lastResult: ActionExecutionResult | null;
+  readonly child: InteractionSnapshot | null;
+}
+
+export interface InteractionRuntimeOptions {
+  readonly interaction: string | InteractionDefinition;
+  readonly runtime: RuntimeContext;
+  readonly context?: Record<string, unknown>;
+  readonly actionRegistry?: ActionRegistry;
+}
+
+export interface InteractionRuntime {
+  getSnapshot(): InteractionSnapshot;
+  send(event: InteractionEvent): Promise<InteractionSnapshot>;
+  callChild(interaction: string | InteractionDefinition, context?: Record<string, unknown>): InteractionRuntime;
+}
+
+function stateByName(spec: InteractionDefinition, name: string): InteractionState | null {
+  return spec.machine.states.find((state) => state.name === name) ?? null;
+}
+
+function guardByName(spec: InteractionDefinition, name: string): SpatialExpression | null {
+  return spec.guards?.find((guard) => guard.name === name)?.expr ?? null;
+}
+
+async function evaluateDisplay(spec: InteractionDefinition, snapshot: InteractionSnapshot, options: InteractionRuntimeOptions): Promise<readonly DisplayItem[]> {
+  const stateDisplay = spec.display?.states?.find((entry) => entry.state === snapshot.state);
+  if (!stateDisplay) return [];
+  const environment: ExpressionEnvironment = {
+    context: snapshot.context,
+    event: {},
+    params: {},
+    variables: {},
+    runtime: options.runtime,
+  };
+  const items: DisplayItem[] = [];
+  for (const item of stateDisplay.items) {
+    switch (item.kind) {
+      case "point":
+        items.push({ kind: item.kind, id: item.id, role: item.role, params: { position: await evalExpression(item.position, environment) } });
+        break;
+      case "label":
+        items.push({ kind: item.kind, id: item.id, role: item.role, params: { text: item.text, position: await evalExpression(item.position, environment) } });
+        break;
+      case "segment":
+        items.push({
+          kind: item.kind,
+          id: item.id,
+          role: item.role,
+          params: { from: await evalExpression(item.from, environment), to: await evalExpression(item.to, environment) },
+        });
+        break;
+      case "linear-handle":
+        items.push({ kind: item.kind, id: item.id, role: item.role, params: { origin: item.origin, axis: item.axis } });
+        break;
+    }
+  }
+  return items;
+}
+
+export class InteractionRegistry {
+  private readonly interactions = new Map<string, InteractionDefinition>();
+
+  constructor(input?: readonly InteractionDefinition[]) {
+    for (const interaction of input ?? []) this.register(interaction);
+  }
+
+  static withBuiltins(): InteractionRegistry {
+    return new InteractionRegistry(listBuiltinInteractions());
+  }
+
+  register(interaction: InteractionDefinition): InteractionDefinition {
+    this.interactions.set(interaction.id, interaction);
+    return interaction;
+  }
+
+  get(id: string): InteractionDefinition | null {
+    return this.interactions.get(id) ?? null;
+  }
+
+  list(): readonly InteractionDefinition[] {
+    return [...this.interactions.values()];
+  }
+}
+
+export function createInteractionRuntime(options: InteractionRuntimeOptions): InteractionRuntime {
+  const interactionRegistry = InteractionRegistry.withBuiltins();
+  const spec = typeof options.interaction === "string" ? interactionRegistry.get(options.interaction) : options.interaction;
+  if (!spec) throw new Error(`Unknown interaction ${String(options.interaction)}.`);
+  const actionRegistry = options.actionRegistry ?? ActionRegistry.withBuiltins();
+  let snapshot: InteractionSnapshot = {
+    interactionId: spec.id,
+    state: spec.machine.initial,
+    context: { ...(options.context ?? {}) },
+    diagnostics: [],
+    display: [],
+    emittedEvents: [],
+    previewRequested: false,
+    lastResult: null,
+    child: null,
+  };
+
+  async function refreshDisplay(): Promise<void> {
+    snapshot = { ...snapshot, display: await evaluateDisplay(spec, snapshot, options) };
+  }
+
+  async function executeEffect(effect: InteractionEffect, event: InteractionEvent): Promise<void> {
+    const environment: ExpressionEnvironment = {
+      context: snapshot.context,
+      event: event as Record<string, unknown>,
+      params: {},
+      variables: {},
+      runtime: options.runtime,
+    };
+    switch (effect.op) {
+      case "assign":
+        writePathSegments(snapshot.context, effect.target.segments, await evalExpression(effect.value, environment));
+        return;
+      case "clear":
+        clearPathSegments(snapshot.context, effect.target.segments);
+        return;
+      case "append": {
+        const current = readPathSegments(snapshot.context, effect.target.segments);
+        const next = Array.isArray(current) ? [...current] : [];
+        next.push(await evalExpression(effect.value, environment));
+        writePathSegments(snapshot.context, effect.target.segments, next);
+        return;
+      }
+      case "emit":
+        snapshot = { ...snapshot, emittedEvents: [...snapshot.emittedEvents, effect.event] };
+        return;
+      case "raise":
+        await runEvent({ kind: effect.event });
+        return;
+      case "openTransaction":
+        if (options.runtime.kernel.openTransaction) await options.runtime.kernel.openTransaction(options.runtime);
+        return;
+      case "commitTransaction":
+        if (options.runtime.kernel.commitTransaction) await options.runtime.kernel.commitTransaction(options.runtime);
+        return;
+      case "rollbackTransaction":
+        if (options.runtime.kernel.rollbackTransaction) await options.runtime.kernel.rollbackTransaction(options.runtime);
+        return;
+      case "requestPreview":
+        if (options.runtime.kernel.requestPreview) await options.runtime.kernel.requestPreview(options.runtime);
+        snapshot = { ...snapshot, previewRequested: true };
+        return;
+      case "kernel.query": {
+        const value = options.runtime.kernel.query ? await options.runtime.kernel.query(effect.query, effect.params, options.runtime) : null;
+        writePathSegments(snapshot.context, effect.assignTo.segments, value);
+        return;
+      }
+      case "resolveEditable":
+        if (options.runtime.kernel.resolveEditable) await options.runtime.kernel.resolveEditable(options.runtime);
+        return;
+      case "setDiagnostic":
+        snapshot = {
+          ...snapshot,
+          diagnostics: [...snapshot.diagnostics.filter((entry) => entry.code !== effect.code), effect],
+        };
+        return;
+      case "clearDiagnostic":
+        snapshot = { ...snapshot, diagnostics: snapshot.diagnostics.filter((entry) => entry.code !== effect.code) };
+        return;
+      case "action": {
+        const result = await actionRegistry.run({
+          action: effect.action,
+          params: await evalExpressionMap(effect.params ?? {}, environment),
+          context: snapshot.context,
+          runtime: options.runtime,
+        });
+        snapshot = { ...snapshot, lastResult: result };
+        if (effect.assignTo) writePathSegments(snapshot.context, effect.assignTo.segments, result.result ?? result.data);
+        return;
+      }
+    }
+  }
+
+  async function maybeCommit(fromState: string, event: InteractionEvent): Promise<void> {
+    const shouldCommitByEvent = spec.commit.when ? spec.commit.when === event.kind : false;
+    const shouldCommitByState = spec.commit.fromStates ? spec.commit.fromStates.includes(fromState) : Boolean(stateByName(spec, snapshot.state)?.final);
+    if (!shouldCommitByEvent && !shouldCommitByState) return;
+    const environment: ExpressionEnvironment = {
+      context: snapshot.context,
+      event: event as Record<string, unknown>,
+      params: {},
+      variables: {},
+      runtime: options.runtime,
+    };
+    const params = await evalExpressionMap(spec.commit.operation.params ?? {}, environment);
+    const result = await actionRegistry.run({
+      action: spec.commit.operation.action,
+      params,
+      context: snapshot.context,
+      runtime: options.runtime,
+    });
+    if (spec.commit.outputDataPath) writePathSegments(snapshot.context, spec.commit.outputDataPath.segments, result.data);
+    snapshot = { ...snapshot, lastResult: result };
+  }
+
+  async function runEvent(event: InteractionEvent): Promise<void> {
+    const currentState = stateByName(spec, snapshot.state);
+    if (!currentState) throw new Error(`Unknown state ${snapshot.state}.`);
+    const handler = currentState.on?.find((entry) => entry.event === event.kind);
+    if (!handler) {
+      await refreshDisplay();
+      return;
+    }
+    for (const transition of handler.transitions) {
+      if (transition.guard) {
+        const guard = guardByName(spec, transition.guard);
+        if (!guard) continue;
+        const passes = Boolean(
+          await evalExpression(guard, {
+            context: snapshot.context,
+            event: event as Record<string, unknown>,
+            params: {},
+            variables: {},
+            runtime: options.runtime,
+          }),
+        );
+        if (!passes) continue;
+      }
+      for (const effect of transition.effects ?? []) await executeEffect(effect, event);
+      const nextState = transition.target ?? snapshot.state;
+      snapshot = { ...snapshot, state: nextState };
+      await maybeCommit(currentState.name, event);
+      await refreshDisplay();
+      return;
+    }
+    await refreshDisplay();
+  }
+
+  const runtime: InteractionRuntime = {
+    getSnapshot(): InteractionSnapshot {
+      return snapshot;
+    },
+    async send(event: InteractionEvent): Promise<InteractionSnapshot> {
+      snapshot = { ...snapshot, emittedEvents: [], previewRequested: false };
+      await runEvent(event);
+      return snapshot;
+    },
+    callChild(interaction: string | InteractionDefinition, context?: Record<string, unknown>): InteractionRuntime {
+      const child = createInteractionRuntime({
+        interaction,
+        context,
+        runtime: options.runtime,
+        actionRegistry,
+      });
+      snapshot = { ...snapshot, child: child.getSnapshot() };
+      return child;
+    },
+  };
+  void refreshDisplay();
+  return runtime;
+}
+// #endregion Interactions
+
+// #region Queries
+export function listModelObjectsByTypology(model: Model, typologyId: string): readonly SpatialObject[] {
+  return model.listObjects().filter((object) => object.typologyId === typologyId);
+}
+
+export function listObjectPrimitives(space: ModelSpace, object: SpatialObject): readonly SpatialPrimitive[] {
+  return object.primitiveHashes.map((hash) => space.getPrimitive(hash)).filter((entry): entry is SpatialPrimitive => entry !== null);
+}
+
+export function listObjectsByAttribute(model: Model, definitionId: string): readonly SpatialObject[] {
+  return model.listObjects().filter((object) => object.attributes.some((attribute) => attribute.definitionId === definitionId));
+}
